import{_ as i,o as s,c as n,ag as t}from"./chunks/framework.CvgP6Fyv.js";const c=JSON.parse('{"title":"SpringBoot项目搭建","description":"","frontmatter":{},"headers":[],"relativePath":"docs/engineering/后端/Java/SpringBoot项目搭建.md","filePath":"docs/engineering/后端/Java/SpringBoot项目搭建.md"}'),e={name:"docs/engineering/后端/Java/SpringBoot项目搭建.md"};function l(r,a,p,o,h,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="springboot项目搭建" tabindex="-1">SpringBoot项目搭建 <a class="header-anchor" href="#springboot项目搭建" aria-label="Permalink to &quot;SpringBoot项目搭建&quot;">​</a></h1><h2 id="创建项目" tabindex="-1">创建项目 <a class="header-anchor" href="#创建项目" aria-label="Permalink to &quot;创建项目&quot;">​</a></h2><h3 id="_1-通过-spring-initializr-创建" tabindex="-1">1. 通过 Spring Initializr 创建 <a class="header-anchor" href="#_1-通过-spring-initializr-创建" aria-label="Permalink to &quot;1. 通过 Spring Initializr 创建&quot;">​</a></h3><p>访问地址：<a href="https://start.spring.io/" target="_blank" rel="noreferrer">https://start.spring.io/</a></p><p><a href="https://lsky-pro.qinlaoshi.dpdns.org:2083/qls/Snipaste_2025-04-29_10-02-54.png" target="_blank" rel="noreferrer">Snipaste_2025-04-29_10-02-54</a></p><p>然后点击页面底部的 &quot;Generate&quot; 按钮，下载一个压缩包（如 demo.zip）。</p><p>最后，解压压缩包，得到一个项目文件夹（如 demo），导入ID。</p><h3 id="_2-通过命令行-curl" tabindex="-1">2. 通过命令行（curl） <a class="header-anchor" href="#_2-通过命令行-curl" aria-label="Permalink to &quot;2. 通过命令行（curl）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://start.spring.io/starter.zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo.zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> type=maven-project</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> language=java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootVersion=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.2.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> groupId=com.example</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artifactId=demo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dependencies=web,lombok</span></span></code></pre></div><h3 id="_3-通过-ide-集成" tabindex="-1">3. 通过 IDE 集成 <a class="header-anchor" href="#_3-通过-ide-集成" aria-label="Permalink to &quot;3. 通过 IDE 集成&quot;">​</a></h3><ul><li>IntelliJ IDEA：新建项目时选择 Spring Initializr，后续步骤与网页版一致。</li><li>VS Code：安装 Spring Boot Extension Pack 插件后，通过命令面板创建。</li></ul><h3 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><ol><li>依赖下载慢：检查 Maven/Gradle 配置是否使用了国内镜像（如阿里云）。</li><li>端口冲突：在 application.properties 中修改 server.port=8081。</li><li>Java 版本不匹配：确保 IDE 和项目的 JDK 版本一致。</li><li>缺少依赖：在 pom.xml 中添加依赖，或者使用 Spring Initializr 创建项目时选择依赖。</li></ol><h2 id="模块拆分" tabindex="-1">模块拆分 <a class="header-anchor" href="#模块拆分" aria-label="Permalink to &quot;模块拆分&quot;">​</a></h2><p>在实际开发中，为了提高代码的可维护性和可扩展性，可以将项目拆分为多个模块。以下是推荐的模块拆分方式：</p><ol><li><p><strong>启动模块（bootstrap）</strong><br> 包含项目的启动类（如 SpringBootApplication 注解的主类），用于启动整个项目。</p></li><li><p><strong>门户模块（portal）</strong><br> 处理用户端的业务逻辑和接口，通常用于对外提供服务。</p></li><li><p><strong>管理模块（admin）</strong><br> 处理后台管理相关的业务逻辑和接口，通常用于内部管理系统。</p></li><li><p><strong>基础模块（common）</strong><br> 包含项目的通用工具类、常量、枚举等，供其他模块复用。</p></li><li><p><strong>配置模块（config）</strong><br> 管理项目的配置文件和配置类。</p></li></ol><h3 id="示例结构" tabindex="-1">示例结构 <a class="header-anchor" href="#示例结构" aria-label="Permalink to &quot;示例结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project-root/</span></span>
<span class="line"><span>├── bootstrap/      # 启动模块</span></span>
<span class="line"><span>├── portal/         # 门户模块</span></span>
<span class="line"><span>├── admin/          # 管理模块</span></span>
<span class="line"><span>├── common/         # 基础模块</span></span>
<span class="line"><span>├── config/         # 配置模块</span></span>
<span class="line"><span>└── pom.xml         # 父模块的 POM 文件</span></span></code></pre></div><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>每个模块应独立开发和测试，尽量减少模块之间的耦合。</li><li>使用 Maven 或 Gradle 的多模块项目结构管理依赖关系。</li><li>根据实际需求调整模块划分，避免过度拆分导致复杂度增加。</li></ul>`,20)])])}const k=i(e,[["render",l]]);export{c as __pageData,k as default};
